<style lang="scss" src="./update-summary-editor-modal.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  destroyModalRootContent,
  ensureModalRoot,
} from "../../util/ensure-modal-root";
import ScrollView from "../scroll-view/scroll-view";
import { MountingPortal } from "portal-vue";
import IconButton from "../icon-button/icon-button.vue";
import Icon from "../icon/icon.vue";
import { IconShape } from "../icon/icon.constants";
import { ButtonMode, ButtonSize } from "../button/button.constants";
import Button from "../button/button";

/**
 * This is the modal portion of updating a summary entry.
 */
@Component({
  components: {
    Button,
    ScrollView,
    MountingPortal,
    IconButton,
    Icon,
  },
})
export default class UpdateSummaryEditorModal extends Vue {
  /**
   * Set this to true to include an image upload property
   */
  @Prop({ type: Boolean, default: false }) allowImageUpload;

  /**
   * This is the root modal element the menu resides in to render floating above
   * all the other elements in the DOM.
   */
  modalRoot = null;
  title = "";
  summary = "";
  image = "";
  IconShape = IconShape;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;

  beforeMount() {
    // HACK: MountingPortal spawns mass duplicates. So as Thanos once said:
    //       Fine. I'll do it myself
    destroyModalRootContent("Menu");
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }

    window.addEventListener("resize", this.handleResize);
  }

  beforeDestroy() {
    window.removeEventListener("resize", this.handleResize);
  }

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get containerStyle() {
    return {
      height: `${window.innerHeight}px`,
    };
  }

  get background() {
    return {
      backgroundImage: `url(${this.image})`,
      height: "500px",
    };
  }

  handleCloseOutside(e) {
    if (e.target !== this.$refs.container) return;
    /**
     * Emits when the user requests the dialogue be closed.
     *
     * @event close
     */
    this.$emit("close");
    e.stopPropagation();
    e.preventDefault();
  }

  handleClose() {
    this.$emit("close");
  }

  handleResize() {
    this.$forceUpdate();
  }

  handleUpdate() {
    /**
     * Emits all of the information in the update when the user clicks to
     * publish the change.
     *
     * Provides: (title, image, summary)
     *
     * @event update
     */
    this.$emit("update", this.title, this.image, this.summary);
  }

  handleCancel() {
    this.$emit("close");
  }

  handleDropImage(e) {
    e.stopPropagation();
    e.preventDefault();
    const files = e.dataTransfer.files;
    this.createFile(files[0]);
  }

  handleImageClose() {
    this.image = void 0;
  }

  handleImageSelect(e) {
    const files = e.target.files;
    this.createFile(files[0]);
  }

  createFile(file) {
    if (!file.type.match("image.*")) {
      alert("Select an image");
      return;
    }
    const reader = new FileReader();
    const vm = this;

    reader.onload = function(e) {
      vm.image = e.target.result;
    };
    reader.readAsDataURL(file);
  }

  /**
   * HACKY HACKS: Due to vue portal having it's own set of issues and we handle
   * its DOM disposal manually, this causes certain scenarios to throw errors
   * from the MountingPortal component. So, we just absorb those issues here for
   * now until better solutions can be discovered or Vue3 is used with better
   * native made portals.
   */
  errorCaptured(err, vm, info) {
    if (info === "beforeDestroy hook") {
      return false;
    }
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div
      class="UpdateSummaryEditorModal"
      :style="containerStyle"
      ref="container"
      @click="handleCloseOutside"
    >
      <div class="UpdateSummaryEditorModal__Body">
        <div class="UpdateSummaryEditorModal__Head">
          <div class="UpdateSummaryEditorModal__HeadTitle">
            Publish an Update to your Fundraising Page
          </div>
          <div class="UpdateSummaryEditorModal__Close" @click="handleClose">
            <Icon
              :shape="IconShape.CLOSE"
              :color="'rgba(2, 0, 38, 0.3)'"
              :size="12"
            />
          </div>
        </div>
        <div class="UpdateSummaryEditorModal__Content">
          <div class="UpdateSummaryEditorModal__Tip">
            This is some help text providing some best-practice tips for keeping
            donors and prospective donors up to date and engaged.
          </div>
          <textarea
            class="UpdateSummaryEditorModal__Title"
            ref="title"
            v-model="title"
          />
          <div v-if="allowImageUpload" class="UpdateSummaryEditorModal__Image">
            <div
              v-if="!Boolean(image)"
              class="UpdateSummaryEditorModal__ImageInput"
            >
              <div
                class="UpdateSummaryEditorModal__AddImage"
                @dragover.prevent
                @drop="handleDropImage"
                @change="handleImageSelect"
              >
                + Add an Image
                <input
                  class="UpdateSummaryEditorModal__ImageSelector"
                  type="file"
                  accept="image/*"
                  @change="handleImageSelect"
                />
              </div>
            </div>
            <div
              v-else
              class="UpdateSummaryEditorModal__FullImage"
              @dragover.prevent
              @drop="handleDropImage"
              :style="background"
            >
              <div
                class="UpdateSummaryEditorModal__ImageClose"
                @click="handleImageClose"
              >
                <Icon
                  :shape="IconShape.CLOSE"
                  :color="'rgba(2, 0, 38, 0.3)'"
                  :size="12"
                />
              </div>
            </div>
          </div>

          <textarea
            class="UpdateSummaryEditorModal__Summary"
            v-model="summary"
          />
          <div class="UpdateSummaryEditorModal__Buttons">
            <Button
              class="UpdateSummaryEditorModal__Button"
              :mode="ButtonMode.PRIMARY"
              :size="ButtonSize.LARGE"
              label="Publish Update"
              @click="handleUpdate"
            />

            <Button
              class="UpdateSummaryEditorModal__Button"
              :mode="ButtonMode.TEXT"
              :size="ButtonSize.LARGE"
              label="Cancel changes"
              @click="handleCancel"
            />
          </div>
        </div>
      </div>
    </div>
  </MountingPortal>
</template>
